// ─── Tests ────────────────────────────────────────────────────────────────────
// Do not edit this file.

package redundantconnection

import (
	"reflect"
	"testing"
)

func check(t *testing.T, edges [][]int, want []int) {
	t.Helper()
	if got := FindRedundantConnection(edges); !reflect.DeepEqual(got, want) {
		t.Fatalf("FindRedundantConnection(%v) = %v, want %v", edges, got, want)
	}
}

func TestTriangle(t *testing.T) {
	check(t, [][]int{{1, 2}, {1, 3}, {2, 3}}, []int{2, 3})
}

func TestCycleWithTail(t *testing.T) {
	check(t, [][]int{{1, 2}, {2, 3}, {3, 4}, {1, 4}, {1, 5}}, []int{1, 4})
}

func TestTwoNodeCycle(t *testing.T) {
	check(t, [][]int{{1, 2}, {2, 1}}, []int{2, 1})
}

// cycle 1-2-3 closes at the 3rd edge; later edges are tree edges
func TestCycleClosedEarly(t *testing.T) {
	check(t, [][]int{{1, 2}, {2, 3}, {3, 1}, {3, 4}, {4, 5}}, []int{3, 1})
}

func TestLongChainClosing(t *testing.T) {
	check(t, [][]int{{2, 3}, {5, 4}, {1, 2}, {4, 3}, {1, 5}}, []int{1, 5})
}

// {1,2} and {3,4} grow separately, join via 2-3, then 1-4 closes the cycle
func TestMergesTwoComponents(t *testing.T) {
	check(t, [][]int{{1, 2}, {3, 4}, {2, 3}, {1, 4}}, []int{1, 4})
}
